#!/usr/bin/env node
/**
 * Generates dev keys for the control plane:
 *
 *   - Ed25519 keypair for control-plane → agent command signing
 *   - 32-byte master secrets key (CP_SECRETS_KEY_PATH) for the SecretBox
 *     envelope that encrypts 2FA secrets / backup codes at rest (C9 seam)
 *
 * DEV ONLY. Production keys are generated by the installer under
 * /etc/nexuspanel/keys/ (root-owned, 0400) — never by this script.
 *
 * Usage:  npm run keys:generate
 * Output: dev-keys/control-plane-signing.key (PEM, gitignored)
 *         dev-keys/control-plane-signing.pub (base64, for the agent's
 *         --signing-pubkey flag)
 *         dev-keys/secrets.key (base64, 0600; point CP_SECRETS_KEY_PATH here)
 */
import { generateKeyPairSync, randomBytes } from 'node:crypto';
import { mkdirSync, writeFileSync, readFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const dir = join(dirname(fileURLToPath(import.meta.url)), '..', 'dev-keys');
mkdirSync(dir, { recursive: true, mode: 0o700 });

const { publicKey, privateKey } = generateKeyPairSync('ed25519');

const pemPriv = privateKey.export({ type: 'pkcs8', format: 'pem' }).toString();
const derPub = publicKey.export({ type: 'spki', format: 'der' });
// The agent consumes the raw 32-byte key as base64 (last 32 bytes of SPKI).
const rawB64 = derPub.subarray(derPub.length - 32).toString('base64');

writeFileSync(join(dir, 'control-plane-signing.key'), pemPriv, { mode: 0o600 });
writeFileSync(join(dir, 'control-plane-signing.pub'), rawB64 + '\n', { mode: 0o644 });

// Master secrets key for the SecretBox (2FA secrets, backup codes).
// Idempotent: never overwrite an existing key — ciphertext already in the
// database depends on it.
const secretsKeyPath = join(dir, 'secrets.key');
if (readFileSyncOrNull(secretsKeyPath)) {
  console.log('dev secrets key already present — left untouched');
} else {
  writeFileSync(secretsKeyPath, randomBytes(32).toString('base64') + '\n', { mode: 0o600 });
}

console.log('dev signing keypair written to dev-keys/');
console.log('control plane:  CP_SIGNING_KEY_PATH=./dev-keys/control-plane-signing.key');
console.log('                CP_SECRETS_KEY_PATH=./dev-keys/secrets.key');
console.log(`agent flag:     --signing-pubkey ${join(dir, 'control-plane-signing.pub')}`);
console.log(`public key b64: ${rawB64}`);
console.log(
  'key file ok:',
  readFileSync(join(dir, 'control-plane-signing.key'), 'utf8').includes('PRIVATE KEY'),
);

function readFileSyncOrNull(path) {
  try {
    return readFileSync(path, 'utf8');
  } catch {
    return null;
  }
}
